pub const EDGE_C_CHUNK: &[u8] = b"0123456789abcdefghij";

/// HTTP/1.1 edge cases on one keep-alive Flow:
/// - a streaming chat request in window 0 whose JSON error response comes in
///   window 1: a Workunit (`application/json` is accepted even with
///   `stream: true`), so window 0's request bytes wait for it;
/// - two pipelined requests in one segment;
/// - a non-streaming completion answered with `text/event-stream`: not a
///   Workunit;
/// - a chunked `/metrics` response whose middle segment, inside chunk data,
///   is lost: a gap that keeps the parser in sync.
pub fn http1_edge() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 3000, 4000);
    let mut f = Vec::new();
    c.handshake(T0 + 100 * MS, &mut f);
    f.push(c.send(true, T0 + 200 * MS, PSH | ACK, EDGE_A_REQ));
    f.push(c.ack(false, T0 + 201 * MS));
    f.push(c.send(false, T0 + 1100 * MS, PSH | ACK, EDGE_A_RESP));
    f.push(c.send(
        true,
        T0 + 1200 * MS,
        PSH | ACK,
        &[EDGE_B_REQ, EDGE_C_REQ].concat(),
    ));
    f.push(c.send(false, T0 + 1300 * MS, PSH | ACK, EDGE_B_RESP));
    let first = [EDGE_C_HEAD, b"14\r\n", &EDGE_C_CHUNK[..5]].concat();
    f.push(c.send(false, T0 + 1310 * MS, ACK, &first));
    let _lost = c.send(false, T0 + 1311 * MS, ACK, &EDGE_C_CHUNK[5..15]);
    let last = [&EDGE_C_CHUNK[15..], b"\r\n0\r\n\r\n"].concat();
    f.push(c.send(false, T0 + 1312 * MS, PSH | ACK, &last));
    f.push(c.ack(true, T0 + 1313 * MS));
    c.close(T0 + 1400 * MS, &mut f);
    Fixture {
        name: "http1_edge",
        files: vec![("http1_edge.pcapng", f)],
    }
}

pub const TLS_CLIENT_HELLO: &[u8] = b"\x16\x03\x01\x00\x2f\x01\x00\x00\x2b\x03\x03\
    \x00\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f\
    \x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\x1a\x1b\x1c\x1d\x1e\x1f\
    \x00\x00\x02\x13\x01\x01\x00\x00\x00";
pub const TLS_SERVER_HELLO: &[u8] = b"\x16\x03\x03\x00\x0a\x02\x00\x00\x06\x03\x03\x00\x13\x01\x00";
pub const TLS_APP_DATA: &[u8] = b"\x17\x03\x03\x00\x05\xde\xad\xbe\xef\x00";

/// A TLS handshake and one application-data record on port 8000 of the
/// plaintext Link: verdict `tls`, every byte unexplained.
pub fn tls_plaintext() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 500, 600);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    f.push(c.send(true, T0 + 20 * MS, PSH | ACK, TLS_CLIENT_HELLO));
    f.push(c.send(false, T0 + 21 * MS, PSH | ACK, TLS_SERVER_HELLO));
    f.push(c.send(true, T0 + 22 * MS, PSH | ACK, TLS_APP_DATA));
    c.close(T0 + 30 * MS, &mut f);
    Fixture {
        name: "tls_plaintext",
        files: vec![("tls_plaintext.pcapng", f)],
    }
}

pub const H2_PREFACE: &[u8] = b"PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n";

pub fn h2_frame(ty: u8, flags: u8, stream: u32, payload: &[u8]) -> Vec<u8> {
    let mut f = (payload.len() as u32).to_be_bytes()[1..].to_vec();
    f.push(ty);
    f.push(flags);
    f.extend_from_slice(&stream.to_be_bytes());
    f.extend_from_slice(payload);
    f
}

/// HPACK header block of literals without indexing, new names, no Huffman.
pub fn hpack_literals(fields: &[(&str, &str)]) -> Vec<u8> {
    let mut b = Vec::new();
    for (n, v) in fields {
        b.extend_from_slice(&[0x00, n.len() as u8]);
        b.extend_from_slice(n.as_bytes());
        b.push(v.len() as u8);
        b.extend_from_slice(v.as_bytes());
    }
    b
}

/// A gRPC call over h2c: parsed as HTTP/2, verdict `grpc`, payload opaque.
pub fn grpc_h2c() -> Fixture {
    const HEADERS: u8 = 1;
    const DATA: u8 = 0;
    const SETTINGS: u8 = 4;
    let mut c = Conn::new(CLIENT, (SERVER.0, 50051), 7000, 8000);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    let req_head = hpack_literals(&[
        (":method", "POST"),
        (":scheme", "http"),
        (":path", "/pkg.Svc/Call"),
        ("content-type", "application/grpc"),
    ]);
    let client = [
        H2_PREFACE,
        &h2_frame(SETTINGS, 0, 0, b""),
        &h2_frame(HEADERS, 0x4, 1, &req_head),
        &h2_frame(DATA, 0x1, 1, b"\x00\x00\x00\x00\x03abc"),
    ]
    .concat();
    f.push(c.send(true, T0 + 20 * MS, PSH | ACK, &client));
    let resp_head = hpack_literals(&[(":status", "200"), ("content-type", "application/grpc")]);
    let server = [
        &h2_frame(SETTINGS, 0, 0, b"")[..],
        &h2_frame(SETTINGS, 0x1, 0, b""),
        &h2_frame(HEADERS, 0x4, 1, &resp_head),
        &h2_frame(DATA, 0, 1, b"\x00\x00\x00\x00\x02ok"),
        &h2_frame(HEADERS, 0x5, 1, &hpack_literals(&[("grpc-status", "0")])),
    ]
    .concat();
    f.push(c.send(false, T0 + 21 * MS, PSH | ACK, &server));
    c.close(T0 + 30 * MS, &mut f);
    Fixture {
        name: "grpc_h2c",
        files: vec![("grpc_h2c.pcapng", f)],
    }
}

pub const CODED_CHAT_REQ: &[u8] =
    b"{\"model\":\"mock-model\",\"messages\":[{\"role\":\"user\",\"content\":\"Say hello\"}]}";
pub const CODED_CHAT_JSON: &[u8] = b"{\"id\":\"chatcmpl-gzip-0001\",\"object\":\"chat.completion\",\"created\":1800000000,\"model\":\"mock-model\",\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"Hello there, friend.\"},\"logprobs\":null,\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":9,\"completion_tokens\":4,\"total_tokens\":13}}";
pub const CODED_STREAM_REQ: &[u8] = b"{\"model\":\"mock-model\",\"stream\":true,\"messages\":[{\"role\":\"user\",\"content\":\"Say hello\"}]}";

/// The SSE events of a streamed chat reply: role, four tokens, finish,
/// `[DONE]`.
pub fn coded_chat_events() -> Vec<Vec<u8>> {
    let base = r#""id":"chatcmpl-gzip-0002","object":"chat.completion.chunk","created":1800000000,"model":"mock-model""#;
    let mut out = vec![format!(
        r#"data: {{{base},"choices":[{{"index":0,"delta":{{"role":"assistant","content":""}},"finish_reason":null}}]}}"#
    )];
    for t in ["Hello", " there", ",", " friend."] {
        out.push(format!(
            r#"data: {{{base},"choices":[{{"index":0,"delta":{{"content":"{t}"}},"finish_reason":null}}]}}"#
        ));
    }
    out.push(format!(
        r#"data: {{{base},"choices":[{{"index":0,"delta":{{}},"finish_reason":"stop"}}]}}"#
    ));
    out.push("data: [DONE]".into());
    out.into_iter().map(|e| format!("{e}\n\n").into_bytes()).collect()
}

/// gzip with no file name and mtime 0, as servers send it.
pub fn gzip(b: &[u8]) -> Vec<u8> {
    use std::io::Write;
    let mut e = flate2::GzBuilder::new().write(Vec::new(), flate2::Compression::default());
    e.write_all(b).unwrap();
    e.finish().unwrap()
}

pub fn zlib(b: &[u8]) -> Vec<u8> {
    use std::io::Write;
    let mut e = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
    e.write_all(b).unwrap();
    e.finish().unwrap()
}

pub fn raw_deflate(b: &[u8]) -> Vec<u8> {
    use std::io::Write;
    let mut e = flate2::write::DeflateEncoder::new(Vec::new(), flate2::Compression::default());
    e.write_all(b).unwrap();
    e.finish().unwrap()
}

pub fn brotli(b: &[u8]) -> Vec<u8> {
    use std::io::Write;
    let mut out = Vec::new();
    {
        let mut w = ::brotli::CompressorWriter::new(&mut out, 4096, 5, 22);
        w.write_all(b).unwrap();
    }
    out
}

pub fn zstd(b: &[u8]) -> Vec<u8> {
    ::zstd::encode_all(b, 3).unwrap()
}

/// A gzip bomb: 8 MiB of zeros, about 8 KiB on the wire.
pub fn gzip_bomb() -> Vec<u8> {
    gzip(&vec![0u8; 8 << 20])
}

/// A chat request (optionally with a coded body) as a Python client sends
/// it: `Accept-Encoding: gzip, deflate`.
pub fn chat_request(body: &[u8], coding: Option<&str>) -> Vec<u8> {
    let mut head = format!(
        "POST /v1/chat/completions HTTP/1.1\r\nHost: 10.0.0.2:8000\r\nAccept-Encoding: gzip, deflate\r\nContent-Type: application/json\r\nContent-Length: {}\r\n",
        body.len()
    );
    if let Some(c) = coding {
        head.push_str(&format!("Content-Encoding: {c}\r\n"));
    }
    head.push_str("\r\n");
    [head.as_bytes(), body].concat()
}

pub fn coded_response(content_type: &str, coding: &str, body: &[u8]) -> Vec<u8> {
    let head = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Encoding: {coding}\r\nContent-Length: {}\r\n\r\n",
        body.len()
    );
    [head.as_bytes(), body].concat()
}

/// Sends `bytes` from a or b in segments of at most `mss`, 1 ms apart.
fn send_all(c: &mut Conn, from_a: bool, ts: u64, bytes: &[u8], mss: usize, f: &mut Vec<Frame>) -> u64 {
    let mut t = ts;
    for piece in bytes.chunks(mss) {
        f.push(c.send(from_a, t, PSH | ACK, piece));
        t += MS;
    }
    f.push(c.ack(!from_a, t));
    t + MS
}

/// A non-streaming chat completion whose JSON response is gzip-coded
/// (`Content-Length`, split across two segments).
pub fn gzip_h1_json() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 11_000, 12_000);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    send_all(
        &mut c,
        true,
        T0 + 20 * MS,
        &chat_request(CODED_CHAT_REQ, None),
        1460,
        &mut f,
    );
    let resp = coded_response("application/json", "gzip", &gzip(CODED_CHAT_JSON));
    send_all(&mut c, false, T0 + 40 * MS, &resp, resp.len() - 40, &mut f);
    c.close(T0 + 60 * MS, &mut f);
    Fixture {
        name: "gzip_h1_json",
        files: vec![("gzip_h1_json.pcapng", f)],
    }
}

/// A streamed chat completion, gzip-coded and chunked, the server flushing
/// the compressor after each event, so every chunk decodes to one event.
pub fn gzip_h1_sse() -> Fixture {
    use std::io::Write;
    let mut c = Conn::new(CLIENT, SERVER, 21_000, 22_000);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    send_all(
        &mut c,
        true,
        T0 + 20 * MS,
        &chat_request(CODED_STREAM_REQ, None),
        1460,
        &mut f,
    );
    let head = b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Encoding: gzip\r\nTransfer-Encoding: chunked\r\n\r\n";
    f.push(c.send(false, T0 + 40 * MS, PSH | ACK, head));
    let mut gz = flate2::GzBuilder::new().write(Vec::new(), flate2::Compression::default());
    let mut t = T0 + 60 * MS;
    let chunk = |b: &[u8]| [format!("{:x}\r\n", b.len()).as_bytes(), b, b"\r\n"].concat();
    for event in coded_chat_events() {
        gz.write_all(&event).unwrap();
        gz.flush().unwrap();
        let wire = std::mem::take(gz.get_mut());
        f.push(c.send(false, t, PSH | ACK, &chunk(&wire)));
        t += 20 * MS;
    }
    let trailer = gz.finish().unwrap();
    f.push(c.send(
        false,
        t,
        PSH | ACK,
        &[chunk(&trailer), b"0\r\n\r\n".to_vec()].concat(),
    ));
    f.push(c.ack(true, t + MS));
    c.close(t + 10 * MS, &mut f);
    Fixture {
        name: "gzip_h1_sse",
        files: vec![("gzip_h1_sse.pcapng", f)],
    }
}

/// One keep-alive Flow, one exchange per case:
/// 0. `deflate` as zlib; 1. `deflate` as raw deflate; 2. `br`; 3. `zstd`;
/// 4. a gzip-coded request body; 5. an unknown coding (`compress`): not
///    read; 6. a gzip bomb: decoding stops at the ratio cap, not read;
/// 7. gzip cut short: `Content-Length` covers a stream with no trailer.
pub fn content_codings_h1() -> Fixture {
    let mut c = Conn::new(CLIENT, SERVER, 31_000, 32_000);
    let mut f = Vec::new();
    c.handshake(T0 + 10 * MS, &mut f);
    let plain = chat_request(CODED_CHAT_REQ, None);
    let json = "application/json";
    let gz = gzip(CODED_CHAT_JSON);
    let cases: Vec<(Vec<u8>, Vec<u8>)> = vec![
        (
            plain.clone(),
            coded_response(json, "deflate", &zlib(CODED_CHAT_JSON)),
        ),
        (
            plain.clone(),
            coded_response(json, "deflate", &raw_deflate(CODED_CHAT_JSON)),
        ),
        (
            plain.clone(),
            coded_response(json, "br", &brotli(CODED_CHAT_JSON)),
        ),
        (
            plain.clone(),
            coded_response(json, "zstd", &zstd(CODED_CHAT_JSON)),
        ),
        (
            chat_request(&gzip(CODED_CHAT_REQ), Some("gzip")),
            coded_response(json, "gzip", &gz),
        ),
        (plain.clone(), coded_response(json, "compress", &gz)),
        (plain.clone(), coded_response(json, "gzip", &gzip_bomb())),
        (plain, coded_response(json, "gzip", &gz[..gz.len() - 8])),
    ];
    let mut t = T0 + 20 * MS;
    for (req, resp) in cases {
        t = send_all(&mut c, true, t, &req, 1460, &mut f);
        t = send_all(&mut c, false, t + 5 * MS, &resp, 1460, &mut f);
        t += 10 * MS;
    }
    c.close(t, &mut f);
    Fixture {
        name: "content_codings_h1",
        files: vec![("content_codings_h1.pcapng", f)],
    }
}

pub fn all() -> Vec<Fixture> {
    vec![
        span_windows(),
        mid_stream(),
        lost_segment(),
        retransmit_differs(),
        udp(),
        dns_covert(),
        non_http_tcp(),
        http1_edge(),
        tls_plaintext(),
        grpc_h2c(),
        gzip_h1_json(),
        gzip_h1_sse(),
        content_codings_h1(),
    ]
}

/// Real traffic from `fixtures/capture/capture.py`, captured with dumpcap
/// on `lo`: the OpenAI and Anthropic SDKs against the mock server, and the
/// Ollama SDK and httpx against a real local Ollama.
pub const CAPTURED: &[&str] = &[
    "openai_h1_json",
    "openai_h1_sse",
    "openai_h2c_json",
    "openai_h2c_sse",
    "http_other_h1",
    "openai_responses_h1_json",
    "openai_responses_h1_sse",
    "openai_responses_h2c_json",
    "openai_responses_h2c_sse",
    "openai_responses_error_h1",
    "ollama_native",
    "ollama_openai_compat",
    "anthropic_h1_json",
    "anthropic_h1_sse",
    "anthropic_h2c_json",
    "anthropic_h2c_sse",
];

pub const DUMPCAP_KEEPALIVE: &[&str] = &[
    "dumpcap_keepalive-1.pcapng",
    "dumpcap_keepalive-2.pcapng",
    "dumpcap_keepalive-3.pcapng",
    "dumpcap_keepalive-4.pcapng",
    "dumpcap_keepalive-5.pcapng",
];

/// Every golden case: (case name, files in read order).
pub fn cases() -> Vec<(String, Vec<String>)> {
    let mut cases: Vec<(String, Vec<String>)> = all()
        .into_iter()
        .map(|fx| {
            (
                fx.name.to_string(),
                fx.files.iter().map(|(n, _)| n.to_string()).collect(),
            )
        })
        .collect();
    cases.push((
        "dumpcap_keepalive".into(),
        DUMPCAP_KEEPALIVE.iter().map(|s| s.to_string()).collect(),
    ));
    for name in CAPTURED {
        cases.push((name.to_string(), vec![format!("{name}.pcapng")]));
    }
    cases
}
